    for categoria in Categoria.objects.all():
        # Generar slug jerárquico
        nombre_slug = slugify(categoria.nombre)
        
        if not categoria.id_categoria_padre:
            categoria.slug = nombre_slug
        else:
            # Construir slug jerárquico
            slugs_padres = []
            padre = categoria.id_categoria_padre
            
            while padre:
                slugs_padres.insert(0, slugify(padre.nombre))
                padre = padre.id_categoria_padre
            
            slugs_padres.append(nombre_slug)
            categoria.slug = "-".join(slugs_padres)
        
        categoria.save(update_fields=['slug'])


